struct SoundScriptManager;
extern SoundScriptManager *sound_manager;
extern "C" int play_event(SoundScriptManager *, int, void *, float)
    __asm__("playEvent__18SoundScriptManager9EventTypeP6entityf");

__asm__(".equ sound_manager, 0x0046B4A0");
__asm__(".equ playEvent__18SoundScriptManager9EventTypeP6entityf, 0x0031C380");

struct menu_vtable {
    char padding[168];
    short adjustment;
    short padding2;
    void (*on_left)(void *, int);
};

struct menu {
    char padding[116];
    menu_vtable *vtable;
};

struct entry {
    int entry_num;
};

struct panel_vtable {
    char padding[24];
    short adjustment;
    short padding2;
    void (*turn_on)(void *, bool);
};

struct panel {
    char padding[404];
    panel_vtable *vtable;
};

struct ExtrasFrontEnd {
    char padding0[76];
    entry *highlighted;
    char padding1[16];
    menu *active;
    char padding2[308];
    menu *surfers;
    menu *beaches;
    menu *trailers;
    char padding3[100];
    panel *arrows[2][2];
    char padding4[4];
    int arrow_counter;
    int arrow_num;

    void OnLeft(int c);
};

static void menu_left(menu *self, int c)
{
    menu_vtable *table = self->vtable;
    table->on_left((char *)self + table->adjustment, c);
}

static void panel_on(panel *self, bool on)
{
    panel_vtable *table = self->vtable;
    table->turn_on((char *)self + table->adjustment, on);
}

void ExtrasFrontEnd::OnLeft(int c)
{
    if (active)
        menu_left(active, c);
    switch (highlighted->entry_num)
    {
    case 0:
        play_event(sound_manager, 26, 0, 0.0f);
        menu_left(beaches, c); break;
    case 1:
        play_event(sound_manager, 26, 0, 0.0f);
        menu_left(surfers, c); break;
    case 2:
        play_event(sound_manager, 26, 0, 0.0f);
        menu_left(trailers, c); break;
    }

    if (highlighted->entry_num <= 2)
    {
        panel_on(arrows[0][1], true);
        panel_on(arrows[0][0], false);
        arrow_num = 0;
        arrow_counter = 3;
    }
}
